fn python_serve_flags_parse_or_are_allowlisted() {
    let known = rust_flags();
    let missing: Vec<&str> = python_flags()
        .into_iter()
        .filter(|flag| !known.contains(*flag) && !PYTHON_ONLY.contains(flag))
        .collect();
    assert!(
        missing.is_empty(),
        "Python `vllm bench serve` flags unknown to vllm-bench: {missing:?}. \
         Support them in src/cli.rs (a clap alias is enough for renames) or \
         add them to PYTHON_ONLY above as a deliberate gap."
    );
}

fn python_only_allowlist_is_not_stale() {
    let known = rust_flags();
    let stale: Vec<&&str> = PYTHON_ONLY.iter().filter(|f| known.contains(**f)).collect();
    assert!(
        stale.is_empty(),
        "PYTHON_ONLY entries now supported by vllm-bench, remove them: {stale:?}"
    );
}

fn python_only_entries_exist_in_snapshot() {
    let snapshot: HashSet<&str> = python_flags().into_iter().collect();
    let gone: Vec<&&str> = PYTHON_ONLY.iter().filter(|f| !snapshot.contains(**f)).collect();
    assert!(
        gone.is_empty(),
        "PYTHON_ONLY entries no longer exist in the Python parser, remove them: {gone:?}"
    );
}

async fn chat_streams_text_events() {
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();
    let engine_id = b"engine-chat".to_vec();

    let (shutdown_tx, engine_task) = spawn_mock_engine_task(
        handshake_address.clone(),
        engine_id.clone(),
        |dealer, push| {
            Box::pin(async move {
                let add = recv_engine_message(dealer).await;
                assert_eq!(add[0].as_ref(), &[0x00]);
                let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
                assert_eq!(request.request_id, "chat-1");
                // more fields here in the future
                assert_eq!(
                    String::from_utf8(
                        decode_prompt_token_ids(&request)
                            .unwrap()
                            .into_iter()
                            .map(|id| id as u8)
                            .collect()
                    )
                    .unwrap(),
                    "system: You are terse.\nuser: Say hi\nassistant:"
                );
                send_outputs(
                    push,
                    RequestBatchOutputs {
                        outputs: vec![
                            request_output("chat-1", vec![b'H' as u32], None, None),
                            request_output(
                                "chat-1",
                                vec![b'i' as u32, b'!' as u32],
                                Some(EngineCoreFinishReason::Stop),
                                Some(StopReason::TokenId(b'!' as u32)),
                            ),
                        ],
                        finished_requests: Some(BTreeSet::from(["chat-1".to_string()])),
                        ..Default::default()
                    }
                    .into(),
                )
                .await;
            })
        },
    );

    let backend: Arc<dyn ChatTextBackend> = Arc::new(FakeChatBackend::new());
    let chat = connect_chat_llm_with_ipc(
        EngineCoreClientConfig::new_single(handshake_address).with_model_name("test-model"),
        &ipc,
        backend,
    )
    .await;

    let mut stream = chat.chat(sample_request("chat-1")).await.unwrap();

    match next_semantic(&mut stream).await.unwrap().unwrap() {
        ChatEvent::Start {
            prompt_token_ids,
            prompt_logprobs: None,
        } => {
            assert_eq!(
                prompt_token_ids.len(),
                "system: You are terse.\nuser: Say hi\nassistant:".len()
            );
            assert!(!prompt_token_ids.is_empty());
        }
        other => panic!("expected Start, got {other:?}"),
    }
    assert_eq!(
        next_semantic(&mut stream).await.unwrap().unwrap(),
        ChatEvent::BlockStart {
            index: 0,
            kind: AssistantBlockKind::Text,
        }
    );
    assert_eq!(
        next_semantic(&mut stream).await.unwrap().unwrap(),
        ChatEvent::BlockDelta {
            index: 0,
            kind: AssistantBlockKind::Text,
            delta: "H".to_string(),
            token_count: None,
        }
    );
    assert_eq!(
        next_semantic(&mut stream).await.unwrap().unwrap(),
        ChatEvent::BlockDelta {
            index: 0,
            kind: AssistantBlockKind::Text,
            delta: "i".to_string(),
            token_count: None,
        }
    );
    assert_eq!(
        next_semantic(&mut stream).await.unwrap().unwrap(),
        ChatEvent::BlockEnd {
            index: 0,
            block: AssistantContentBlock::Text {
                text: "Hi".to_string(),
            },
        }
    );

    match next_semantic(&mut stream).await {
        Some(Ok(ChatEvent::Done {
            message,
            usage,
            finish_reason,
            ..
        })) => {
            assert_eq!(message.text(), "Hi");
            assert_eq!(usage.output_token_count, 3);
            assert_eq!(
                finish_reason,
                FinishReason::Stop(Some(StopReason::TokenId(b'!' as u32)))
            );
        }
        other => panic!("unexpected final event: {other:?}"),
    }
    assert!(next_semantic(&mut stream).await.is_none());

    let _ = shutdown_tx.send(());
    engine_task.await.unwrap();
    chat.shutdown().await.unwrap();
}

