    };

    assert!(matches!(
        error,
        vllm_chat::Error::ParserUnavailableByName { name, .. }
        if name == "definitely_missing_tool_parser"
    ));

    let _ = shutdown_tx.send(());
    engine_task.await.unwrap();
    chat.shutdown().await.unwrap();
}

