fn client_config_validates_bootstrapped_dp_range() {
    // Validation never consumes the descriptors, so placeholders avoid opening
    // listeners that nothing would close.
    let mut config = EngineCoreClientConfig {
        transport_mode: TransportMode::Bootstrapped {
            input_listener_fd: -1,
            output_listener_fd: -1,
            engine_start_index: 1,
            engine_count: 2,
            data_parallel_size: 3,
            ready_timeout: Duration::from_secs(1),
        },
        coordinator_mode: None,
        model_name: "test-model".to_string(),
        client_index: 0,
        engine_stats_enabled: true,
    };
    config.validate().expect("frontend may own a subset of global DP ranks");

    let TransportMode::Bootstrapped {
        data_parallel_size, ..
    } = &mut config.transport_mode
    else {
        unreachable!("expected bootstrapped transport")
    };
    *data_parallel_size = 2;
    let error = config.validate().expect_err("engine range above DP size must fail");
    expect_test::expect![[
        "invalid engine-core client configuration: connected engine range [1, 3) exceeds data parallel size (2)"
    ]]
    .assert_eq(&error.to_string());
}

fn client_transport_outlives_connecting_runtime() {
    init_tracing();
    let caller = Builder::new_current_thread().enable_all().build().unwrap();
    let independent = Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();
    let (shutdown_tx, engine_task) = independent.block_on(async {
        spawn_mock_engine_task(
            handshake_address.clone(),
            vec![0x00, 0x00],
            |dealer, push| {
                Box::pin(async move {
                    let _request = recv_engine_message(dealer).await;
                    send_outputs(
                        push,
                        RequestBatchOutputs {
                            outputs: vec![request_output(
                                "req-1",
                                vec![42],
                                Some(EngineCoreFinishReason::Length),
                            )],
                            ..Default::default()
                        }
                        .into(),
                    )
                    .await;
                })
            },
        )
    });
    let client = caller.block_on(connect_client_with_ipc(
        handshake_test_config(
            handshake_address,
            1,
            "test-model",
            Duration::from_secs(2),
            0,
            None,
        ),
        &ipc,
    ));

    caller.shutdown_timeout(Duration::from_secs(1));

    let mut stream = independent
        .block_on(client.call(sample_request()))
        .expect("the client owns its transport runtime")
        .into_outputs();
    let output = independent
        .block_on(async { timeout(Duration::from_secs(2), stream.next()).await })
        .expect("engine output timed out")
        .expect("engine output stream ended")
        .expect("engine output failed");
    assert_eq!(output.new_token_ids, [42]);

    let _ = shutdown_tx.send(());
    independent.block_on(engine_task).unwrap();
    independent.block_on(client.shutdown()).unwrap();
}

async fn coordinator_handshake_includes_engine_control_addresses() {
    init_tracing();
    let ipc = IpcNamespace::new().unwrap();
    let mut engines = Vec::new();
    for engine_id in [[0x00, 0x00], [0x01, 0x00]] {
        let handshake_address = ipc.handshake_endpoint();
        let (init_tx, init_rx) = oneshot::channel();
        let (shutdown_tx, shutdown_rx) = oneshot::channel();
        let engine_task = tokio::spawn(async move {
            let sockets = setup_mock_engine_sockets(handshake_address, &engine_id).await;
            let _ = init_tx.send(sockets.init.clone());
            let _ = shutdown_rx.await;
        });
        engines.push((init_rx, shutdown_tx, engine_task));
    }

    let client = connect_client_with_ipc(
        handshake_test_config(
            ipc.handshake_endpoint(),
            2,
            "test-model",
            Duration::from_secs(2),
            0,
            Some(CoordinatorMode::InProc),
        ),
        &ipc,
    )
    .await;

    let mut inits = Vec::new();
    for (init_rx, shutdown_tx, engine_task) in engines {
        inits.push(init_rx.await.unwrap());
        let _ = shutdown_tx.send(());
        engine_task.await.unwrap();
    }
    let init = &inits[0];
    assert_eq!(init.parallel_config, inits[1].parallel_config);
    assert!(init.addresses.coordinator_input.is_some());
    assert!(init.addresses.coordinator_output.is_some());
    assert!(init.addresses.frontend_stats_publish_address.is_some());

    // Coordinated DP sends one DP rendezvous to every engine: the handshake
    // host plus five distinct ports.
    let rendezvous = init
        .parallel_config
        .data_parallel_rendezvous
        .as_ref()
        .expect("coordinated DP sends the DP rendezvous");
    assert_eq!(rendezvous.data_parallel_master_ip, "127.0.0.1");
    assert_eq!(rendezvous.data_parallel_size, 2);
    let mut ports = rendezvous.data_parallel_master_port_list.clone();
    assert_eq!(ports.len(), 4);
    ports.push(rendezvous.data_parallel_master_port);
    ports.sort_unstable();
    ports.dedup();
    assert_eq!(ports.len(), 5);
    assert!(!ports.contains(&0));

    client.shutdown().await.unwrap();
}

async fn coordinator_wave_control_tracks_pause_running_and_rebroadcasts() {
    init_tracing();
    let ipc = IpcNamespace::new().unwrap();
    let handshake_address = ipc.handshake_endpoint();

    let (shutdown0_tx, shutdown0_rx) = oneshot::channel();
    let engine0_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x00, 0x00]).await;
            let coordinator_address = engine
                .init
                .addresses
                .coordinator_input
                .clone()
                .expect("coordinator input address should be present");
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");
            let data_socket = engine.data_sockets.first_mut().expect("data socket");

            // An idle engine handed a request starts the wave itself.
            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-1");
            assert_eq!(request.current_wave, 0);
            send_start_wave(&mut coordinator.output_push, 0, 0).await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (0, Some(0)));

            let mut late_subscriber = SubSocket::new();
            late_subscriber.connect(&coordinator_address).await.unwrap();
            late_subscriber.subscribe("").await.unwrap();

            let replay = recv_start_dp_wave(&mut late_subscriber).await;
            assert_eq!(replay, (0, None));
            let replay = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!(replay, (0, None));

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_start_dp_wave(&mut coordinator.input_sub)
                )
                .await
                .is_err()
            );

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    outputs: vec![request_output(
                        "req-1",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-1".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            send_outputs(
                &mut coordinator.output_push,
                DpControlOutput {
                    engine_index: 0,
                    timestamp: 0.0,
                    control: DpControlMessage::WaveComplete(0),
                }
                .into(),
            )
            .await;

            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-3");
            assert_eq!(request.current_wave, 1);
            send_start_wave(&mut coordinator.output_push, 0, 1).await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (1, Some(0)));

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    outputs: vec![request_output(
                        "req-3",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-3".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            let _ = shutdown0_rx.await;
        }
    });

    let (shutdown1_tx, shutdown1_rx) = oneshot::channel();
    let engine1_task = tokio::spawn({
        let handshake_address = handshake_address.clone();
        async move {
            let mut engine = setup_mock_engine_sockets(handshake_address, &[0x01, 0x00]).await;
            let mut coordinator =
                engine.coordinator.take().expect("coordinator sockets should be present");
            let data_socket = engine.data_sockets.first_mut().expect("data socket");

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (0, Some(0)));
            let replay = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!(replay, (0, None));

            let add = recv_engine_message(&mut data_socket.dealer).await;
            assert_eq!(add[0].as_ref(), &[0x00]);
            let request: EngineCoreRequest = rmp_serde::from_slice(&add[1]).unwrap();
            assert_eq!(request.request_id, "req-2");
            assert_eq!(request.current_wave, 0);

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_start_dp_wave(&mut coordinator.input_sub)
                )
                .await
                .is_err()
            );

            send_outputs(
                &mut data_socket.push,
                RequestBatchOutputs {
                    engine_index: 1,
                    outputs: vec![request_output(
                        "req-2",
                        vec![],
                        Some(EngineCoreFinishReason::Length),
                    )],
                    finished_requests: Some(BTreeSet::from(["req-2".to_string()])),
                    ..Default::default()
                }
                .into(),
            )
            .await;

            let (wave, exclude_engine) = recv_start_dp_wave(&mut coordinator.input_sub).await;
            assert_eq!((wave, exclude_engine), (1, Some(0)));

            assert!(
                timeout(
                    Duration::from_millis(200),
                    recv_engine_message(&mut data_socket.dealer)
                )
                .await
                .is_err()
            );

            let _ = shutdown1_rx.await;
        }
    });

    let client = connect_client_with_ipc(
